const crypto = require('crypto');

const findText = (obj) => {
  if (typeof obj === 'string') return obj;

  const picks = [];
  const push = (v) => {
    if (typeof v === 'string' && v.trim()) picks.push(v);
  };

  push(obj.text);
  push(obj.output_text);
  push(obj.data);
  push(obj.completion);
  push(obj.output);
  if (obj.message?.text) push(obj.message.text);
  if (Array.isArray(obj.messages) && obj.messages[0]?.text) push(obj.messages[0].text);

  try {
    const parts = obj.candidates?.[0]?.content?.parts || [];
    const joined = parts.map(p => p.text).filter(Boolean).join('
');
    push(joined);
  } catch (e) {}

  if (obj.data && typeof obj.data === 'object') {
    push(obj.data.text);
    push(obj.data.output_text);
    push(obj.data.completion);
  }

  return picks[0] ?? JSON.stringify(obj);
};

const extractJsonString = (s) => {
  s = String(s ?? '').trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  if (!s.startsWith('{')) {
    const i = s.indexOf('{');
    const j = s.lastIndexOf('}');
    if (i !== -1 && j !== -1 && j > i) s = s.slice(i, j + 1);
  }
  return s;
};

const rawText = findText($json);
const jsonStr = extractJsonString(rawText);

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  throw new Error(
    'Could not parse JSON from model output.
' +
    'First 400 chars were:
' + (rawText || '').slice(0, 400)
  );
}

['events', 'snack_changes', 'allergy_changes', 'notices'].forEach(k => {
  if (!(k in parsed)) {
    parsed[k] = [];
  }
  if (!Array.isArray(parsed[k])) {
    throw new Error(`Field ${k} must be an array. Got: ${typeof parsed[k]}`);
  }
});

const meta = $json.__ingestion || {};
const baseSourceType = meta.source_type || meta.ingestion_origin || null;
const baseSourceUrl = meta.source_url || null;
const sourceId = meta.message_id || meta.file_id || null;
const sourceSubject = meta.subject || meta.source_subject || meta.subject || null;
const fileName = meta.file_name || meta.source_file_name || null;
const ingestedAt = meta.ingested_at || null;
const attachments = Array.isArray(meta.attachments) ? meta.attachments : [];
const ocrStatus = meta.ocr_status || null;
const pdfError = meta.pdf_parse_error || null;

const computeItemId = (scope, payload) => {
  const hashInput = {
    scope,
    source_type: baseSourceType,
    source_url: baseSourceUrl,
    source_id: sourceId,
    payload,
  };
  return crypto.createHash('sha1').update(JSON.stringify(hashInput)).digest('hex');
};

const annotate = (list, scope) => list.map(item => {
  const enriched = { ...item };
  enriched.source_type = baseSourceType;
  enriched.source_url = baseSourceUrl;
  if (sourceId) enriched.source_id = sourceId;
  if (sourceSubject) enriched.source_subject = sourceSubject;
  if (fileName) enriched.source_file_name = fileName;
  if (ingestedAt) enriched.ingested_at = ingestedAt;
  if (attachments.length) enriched.source_attachments = attachments;
  if (ocrStatus) enriched.source_ocr_status = ocrStatus;
  if (pdfError) enriched.source_pdf_error = pdfError;
  enriched.item_id = computeItemId(scope, item);
  return enriched;
});

parsed.events = annotate(parsed.events, 'event');
parsed.snack_changes = annotate(parsed.snack_changes, 'snack');
parsed.allergy_changes = annotate(parsed.allergy_changes, 'allergy');
parsed.notices = annotate(parsed.notices, 'notice');

parsed._source = {
  source_type: baseSourceType,
  source_url: baseSourceUrl,
  source_id: sourceId,
  subject: sourceSubject,
  file_name: fileName,
  ingested_at: ingestedAt,
};
if (attachments.length) parsed._source.attachments = attachments;
if (meta.gmail_metadata) parsed._source.gmail_metadata = meta.gmail_metadata;
if (ocrStatus) parsed._source.ocr_status = ocrStatus;
if (pdfError) parsed._source.pdf_parse_error = pdfError;
if (meta.prompt_template) parsed._source.prompt_template = meta.prompt_template;

return [{ json: parsed }];

const tzDefault = 'America/Los_Angeles';

function slugify(input) {
  return String(input ?? '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, '-');
}

function parseWeekRange(label) {
  if (!label) return null;
  const clean = String(label).replace(/\s+/g, ' ').trim();
  const rangeRe = /([A-Za-z]{3,})\.?\s*(\d{1,2})(?:[–-]\s*([A-Za-z]{3,})\.?\s*(\d{1,2}))?/;
  const match = clean.match(rangeRe);
  if (!match) return null;
  const months = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
  const startMonthIndex = months.indexOf(match[1].slice(0, 3).toLowerCase());
  if (startMonthIndex === -1) return null;
  const startDay = Number(match[2]);
  let endMonthIndex = startMonthIndex;
  let endDay = Number(match[4] || match[2]);
  if (match[3]) {
    const idx = months.indexOf(match[3].slice(0, 3).toLowerCase());
    if (idx !== -1) endMonthIndex = idx;
  }
  const now = new Date();
  const year = now.getFullYear();
  const start = new Date(Date.UTC(year, startMonthIndex, startDay, 0, 0, 0));
  const end = new Date(Date.UTC(year, endMonthIndex, endDay, 23, 59, 59));
  if (Number.isNaN(start.valueOf()) || Number.isNaN(end.valueOf())) return null;
  return { start_iso: start.toISOString(), end_iso: end.toISOString() };
}

function ensureIso(value) {
  if (!value) return null;
  if (value instanceof Date) return value.toISOString();
  if (typeof value === 'number') return new Date(value).toISOString();
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (!trimmed) return null;
  const direct = new Date(trimmed);
  if (!Number.isNaN(direct.valueOf())) return direct.toISOString();
  const dateOnly = trimmed.match(/\d{4}-\d{2}-\d{2}/);
  if (dateOnly) {
    const parsed = new Date(dateOnly[0] + 'T00:00:00.000Z');
    if (!Number.isNaN(parsed.valueOf())) return parsed.toISOString();
  }
  return null;
}

function calendarTimeToIso(entry, { isEnd = false } = {}) {
  if (!entry) return null;
  if (typeof entry === 'string') return ensureIso(entry);
  if (entry.dateTime) return ensureIso(entry.dateTime);
  if (entry.date) {
    const suffix = isEnd ? 'T23:59:59.000Z' : 'T00:00:00.000Z';
    return ensureIso(entry.date + suffix);
  }
  return null;
}

function makeCalendarKey(summary, startIso) {
  const titlePart = slugify(summary);
  const timePart = startIso ? startIso.slice(0, 16) : 'no-time';
  return titlePart + '|' + timePart;
}

function normalizeCalendar(events) {
  return events.map((event) => {
    const startIso = calendarTimeToIso(event.start);
    const endIso = calendarTimeToIso(event.end, { isEnd: true }) || startIso;
    return {
      event_id: event.id || event.eventId || event.iCalUID || null,
      summary: String(event.summary || '').trim(),
      description: String(event.description || '').trim() || undefined,
      location: String(event.location || '').trim() || undefined,
      start_iso: startIso,
      end_iso: endIso,
      all_day: Boolean(event.start && event.start.date && !event.start.dateTime),
      html_link: event.htmlLink || undefined,
      dedupe_key: makeCalendarKey(event.summary || '', startIso),
      source_refs: event.htmlLink ? [{ url: event.htmlLink, type: 'calendar', item_id: event.id || null }] : undefined,
      raw: event
    };
  });
}

function normalizeSnackRows(rows) {
  return rows
    .map((row, index) => {
      const weekLabel = String(row.Week ?? row.week ?? '').trim();
      if (!weekLabel) return null;
      const range = parseWeekRange(weekLabel);
      const weekKey = range ? range.start_iso.slice(0, 10) : slugify(weekLabel);
      const child = String(row.Child ?? row.child ?? '').trim();
      const rowIndex = row.rowIndex ?? row.$row ?? row.__sheetRow ?? (index + 2);
      return {
        week_label: weekLabel,
        week_key: weekKey,
        child,
        range,
        row_index: rowIndex,
        raw: row
      };
    })
    .filter(Boolean);
}

function normalizeAllergies(rows) {
  return rows
    .map((row) => {
      const text = row.Allergy ?? row.allergy ?? row.text ?? row.note;
      const trimmed = String(text || '').trim();
      if (!trimmed) return null;
      return { text: trimmed, raw: row };
    })
    .filter(Boolean);
}

function buildSourceRefs(record, topSource) {
  const refs = [];
  const addRef = (ref) => {
    if (!ref || !ref.url) return;
    const exists = refs.some((existing) => existing.url === ref.url && existing.type === ref.type);
    if (!exists) refs.push(ref);
  };

  const directRefs = Array.isArray(record.source_refs) ? record.source_refs : [];
  for (const ref of directRefs) {
    if (!ref) continue;
    addRef({
      url: String(ref.url || ref.href || ''),
      type: ref.type || ref.source_type || record.source_type || topSource?.source_type || null,
      item_id: ref.item_id || record.item_id || null,
      label: ref.label || ref.title || null
    });
  }

  if (record.source_url) {
    addRef({
      url: String(record.source_url),
      type: record.source_type || record.source || topSource?.source_type || null,
      item_id: record.item_id || record.source_id || topSource?.source_id || null,
      label: record.source_subject || topSource?.subject || null
    });
  }

  if (topSource && topSource.source_url) {
    addRef({
      url: String(topSource.source_url),
      type: topSource.source_type || null,
      item_id: topSource.source_id || null,
      label: topSource.subject || topSource.file_name || null
    });
  }

  return refs.length ? refs : undefined;
}

function normalizeProposed(extractor) {
  const events = Array.isArray(extractor.events) ? extractor.events : [];
  const snackChanges = Array.isArray(extractor.snack_changes) ? extractor.snack_changes : [];
  const allergyChanges = Array.isArray(extractor.allergy_changes) ? extractor.allergy_changes : [];
  const notices = Array.isArray(extractor.notices) ? extractor.notices : [];
  const topSource = extractor._source || null;

  const normEvents = events.map((event, index) => {
    const summary = String(event.title ?? event.summary ?? '').trim();
    const startIso = ensureIso(event.start_iso ?? event.start);
    const endIso = ensureIso(event.end_iso ?? event.end);
    return {
      index,
      op: String(event.op || 'upsert').toLowerCase(),
      summary,
      start_iso: startIso,
      end_iso: endIso || null,
      location: String(event.location || '').trim() || undefined,
      description: String(event.description ?? event.notes ?? '').trim() || undefined,
      audience: event.audience || undefined,
      dedupe_key: makeCalendarKey(summary, startIso),
      item_id: event.item_id || event.source_item_id || null,
      source_refs: buildSourceRefs(event, topSource),
      raw: event
    };
  });

  const normSnack = snackChanges.map((row, index) => {
    const weekLabel = String(row.week_label ?? row.week_text ?? row.week ?? '').trim();
    const range = parseWeekRange(weekLabel);
    const weekKey = range ? range.start_iso.slice(0, 10) : slugify(weekLabel);
    return {
      index,
      week_label: weekLabel,
      week_key: weekKey,
      child: String(row.child ?? row.assignee ?? '').trim(),
      note: String(row.note ?? row.notes ?? '').trim() || undefined,
      item_id: row.item_id || null,
      source_refs: buildSourceRefs(row, topSource),
      raw: row
    };
  });

  const normAllergy = allergyChanges.map((row, index) => {
    const action = String(row.action ?? row.op ?? '').toLowerCase();
    const payload = row.allergy_text ?? row.item ?? row.text ?? '';
    return {
      index,
      action,
      child: row.child || row.student || null,
      allergy_text: typeof payload === 'string' ? payload.trim() : payload,
      source_refs: buildSourceRefs(row, topSource),
      raw: row
    };
  });

  const normNotices = notices.map((notice, index) => ({
    index,
    text: String(notice.text ?? '').trim(),
    audience: notice.audience || undefined,
    priority: notice.priority || undefined,
    source_refs: buildSourceRefs(notice, topSource),
    raw: notice
  }));

  return { events: normEvents, snack_changes: normSnack, allergy_changes: normAllergy, notices: normNotices, topSource };
}

const aggregator = {
  runContext: null,
  extractor: null,
  calendar: [],
  snackRows: [],
  allergyRows: [],
  opsRows: [],
  debugKeys: []
};

for (let inputIndex = 0; inputIndex < 8; inputIndex++) {
  let items;
  try {
    items = $items(inputIndex);
  } catch (err) {
    continue;
  }
  if (!items || !items.length) continue;
  for (const item of items) {
    const json = item && item.json ? item.json : null;
    if (!json || typeof json !== 'object') continue;
    const keys = Object.keys(json);
    aggregator.debugKeys.push(keys);
    if (json.poll_start_iso || json.poll_end_iso || json.lookback_start_iso) {
      aggregator.runContext = { ...(aggregator.runContext || {}), ...json };
      continue;
    }
    if (!aggregator.extractor && (Array.isArray(json.events) || Array.isArray(json.snack_changes))) {
      aggregator.extractor = json;
      continue;
    }
    if (json.kind === 'calendar#event' || json.start || json.summary) {
      aggregator.calendar.push(json);
      continue;
    }
    if ('Week' in json || 'Child' in json || 'week' in json) {
      aggregator.snackRows.push(json);
      continue;
    }
    if ('Allergy' in json || 'allergy' in json || 'Allergies' in json) {
      aggregator.allergyRows.push(json);
      continue;
    }
    if ('Action' in json || 'Target' in json || 'Diff' in json || 'timestamp' in json) {
      aggregator.opsRows.push(json);
      continue;
    }
  }
}

if (!aggregator.extractor) {
  throw new Error('Compile Current State: missing extractor payload. Saw input key sets: ' + JSON.stringify(aggregator.debugKeys.slice(0, 5)));
}

const runContext = aggregator.runContext || {};
if (!runContext.tz) runContext.tz = tzDefault;
const meta = {
  generated_at_iso: new Date().toISOString(),
  tz: runContext.tz,
  poll_start_iso: runContext.poll_start_iso || null,
  poll_end_iso: runContext.poll_end_iso || null,
  lookback_start_iso: runContext.lookback_start_iso || null,
  lookback_end_iso: runContext.lookback_end_iso || null
};

const current = {
  calendar: normalizeCalendar(aggregator.calendar),
  snacks: normalizeSnackRows(aggregator.snackRows),
  allergies: normalizeAllergies(aggregator.allergyRows),
  opslog: aggregator.opsRows
};

const proposed = normalizeProposed(aggregator.extractor);

return [{
  json: {
    meta,
    current,
    proposed,
    debug: {
      source_counts: {
        calendar: aggregator.calendar.length,
        snack_rows: aggregator.snackRows.length,
        allergy_rows: aggregator.allergyRows.length,
        ops_rows: aggregator.opsRows.length
      }
    }
  }
}];

const crypto = require('crypto');

const input = ($json && typeof $json === 'object') ? $json : {};
const store = $getWorkflowStaticData('global');
if (!store || typeof store !== 'object') {
  throw new Error('Static data unavailable for approval link generation.');
}
if (!store.approvalsHmacSecret) {
  throw new Error('Approvals HMAC secret not set. Run Setup Approvals Secret first.');
}

const ttlHours = 24;
const ttlMs = ttlHours * 60 * 60 * 1000;

const meta = input.meta || {};
const adminRows = Array.isArray(input.admin_rows) ? input.admin_rows : [];
const pendingStore = (store.pendingApprovals && typeof store.pendingApprovals === 'object') ? store.pendingApprovals : {};

const diffIso = meta.diff_generated_at_iso || meta.generated_at_iso || new Date().toISOString();
const diffMs = Date.parse(diffIso) || Date.now();

const baseUrlString = `${$execution.resumeUrl}`.replace('/webhook-waiting/', '/webhook/');

function buildUrl(action, token, ts) {
  const url = new URL(baseUrlString);
  url.pathname = url.pathname.replace(/\/[^/]*$/, `/room-parent/${action}`);
  url.search = '';
  url.searchParams.set('token', token);
  url.searchParams.set('action', action);
  url.searchParams.set('ts', ts);
  return url.toString();
}

function signPayload(token, action, ts) {
  const canonical = JSON.stringify({ token, action, ts });
  const digest = crypto
    .createHmac('sha256', store.approvalsHmacSecret)
    .update(canonical)
    .digest('hex');
  return {
    canonical,
    signature: `sha256=${digest}`,
  };
}

if (!adminRows.length) {
  return [{
    json: {
      ...input,
      approvals: {
        count: 0,
        ttl_hours: ttlHours,
        generated_at_iso: diffIso,
        items: [],
      },
      admin_sheet_rows_signed: [],
      pending_tokens: input.pending_tokens || [],
    },
  }];
}

const signedSheetRows = [];
const emailItems = [];
const tokens = new Set(input.pending_tokens || []);

for (const row of adminRows) {
  const token = row.token;
  if (!token) {
    continue;
  }

  const ts = row.when_found_iso || diffIso;
  const tsMs = Date.parse(ts) || diffMs;
  const expiresAt = new Date(tsMs + ttlMs).toISOString();

  const approveSignature = signPayload(token, 'approve', ts);
  const rejectSignature = signPayload(token, 'reject', ts);
  const approveUrl = buildUrl('approve', token, ts);
  const rejectUrl = buildUrl('reject', token, ts);

  const existing = (pendingStore[token] && typeof pendingStore[token] === 'object') ? pendingStore[token] : {};
  const status = existing.status || 'Pending';

  const scope = existing.scope
    || row.scope
    || (row.hmac_payload && typeof row.hmac_payload.action === 'string'
      ? row.hmac_payload.action.split('.')[0]
      : null);

  existing.token = token;
  existing.scope = scope;
  existing.op = existing.op || row.op || null;
  existing.created_at = existing.created_at || ts;
  existing.expires_at = expiresAt;
  existing.hmac_payload = existing.hmac_payload || row.hmac_payload || null;
  existing.admin_row = {
    ...row,
    status,
  };
  existing.status = status;
  existing.links = {
    approve: { url: approveUrl, signature: approveSignature.signature, ts },
    reject: { url: rejectUrl, signature: rejectSignature.signature, ts },
    ttl_hours: ttlHours,
    expires_at: expiresAt,
  };

  pendingStore[token] = existing;

  signedSheetRows.push({
    WhenFound: row.when_found_iso || diffIso,
    Type: row.type || (scope ? scope.charAt(0).toUpperCase() + scope.slice(1) : ''),
    Summary: row.summary || '',
    Detail: row.detail || '',
    SourceLink: row.source_url || '',
    SourceType: row.source_type || '',
    ApproveLink: approveUrl,
    RejectLink: rejectUrl,
    Status: status,
    Token: token,
    Action: (row.hmac_payload && row.hmac_payload.action) || (existing.hmac_payload && existing.hmac_payload.action) || '',
    ExpiresAt: expiresAt,
    ProcessedAt: existing.closed_at_iso || '',
    Actor: existing.actor || '',
  });

  emailItems.push({
    token,
    type: row.type || scope || '',
    summary: row.summary || '',
    detail: row.detail || '',
    whenFound: row.when_found_iso || diffIso,
    sourceLink: row.source_url || '',
    sourceType: row.source_type || '',
    expiresAt,
    ts,
    approvals: {
      approve: {
        action: 'approve',
        url: approveUrl,
        headers: { 'X-Signature': approveSignature.signature },
        payload: { token, action: 'approve', ts },
      },
      reject: {
        action: 'reject',
        url: rejectUrl,
        headers: { 'X-Signature': rejectSignature.signature },
        payload: { token, action: 'reject', ts },
      },
    },
  });

  tokens.add(token);
}

store.pendingApprovals = pendingStore;
store.pendingApprovalsCount = Object.values(pendingStore)
  .filter((record) => (record && (record.status || 'Pending') === 'Pending')).length;

return [{
  json: {
    ...input,
    approvals: {
      count: emailItems.length,
      ttl_hours: ttlHours,
      generated_at_iso: diffIso,
      items: emailItems,
    },
    admin_sheet_rows_signed: signedSheetRows,
    pending_tokens: Array.from(tokens),
  },
}];

const crypto = require('crypto');

const store = $getWorkflowStaticData('global');
if (!store || !store.approvalsHmacSecret) {
  throw new Error('Approvals HMAC secret not configured.');
}

const req = $json || {};
const headerMap = {};
if (req.headers && typeof req.headers === 'object') {
  for (const [key, value] of Object.entries(req.headers)) {
    const normalized = key.toLowerCase();
    headerMap[normalized] = Array.isArray(value) ? value[0] : value;
  }
}

const signatureHeader = headerMap['x-signature'];
if (!signatureHeader) {
  throw new Error('Missing X-Signature header.');
}

const match = /^sha256=([a-f0-9]{64})$/i.exec(String(signatureHeader).trim());
if (!match) {
  throw new Error('Invalid X-Signature format.');
}
const providedHex = match[1].toLowerCase();

function coerceObject(value) {
  if (value && typeof value === 'object') {
    return value;
  }
  if (typeof value === 'string' && value.trim()) {
    try { return JSON.parse(value); } catch (_) { /* ignore */ }
  }
  return {};
}

const body = coerceObject(req.body);
const query = coerceObject(req.query);

const token = String(body.token ?? query.token ?? '').trim();
const action = String(body.action ?? query.action ?? '').trim().toLowerCase();
const ts = String(body.ts ?? query.ts ?? '').trim();
const actor = body.actor ?? query.actor ?? null;

if (!token || !action || !ts) {
  throw new Error('Missing token/action/ts payload fields.');
}

const canonical = JSON.stringify({ token, action, ts });
const expectedHex = crypto
  .createHmac('sha256', store.approvalsHmacSecret)
  .update(canonical)
  .digest('hex');

const provided = Buffer.from(providedHex, 'hex');
const expected = Buffer.from(expectedHex, 'hex');
if (provided.length !== expected.length || !crypto.timingSafeEqual(provided, expected)) {
  throw new Error('Signature mismatch.');
}

const tsDate = new Date(ts);
if (Number.isNaN(tsDate.getTime())) {
  throw new Error('Invalid ts value.');
}
const maxAgeMs = 24 * 60 * 60 * 1000;
if (Math.abs(Date.now() - tsDate.getTime()) > maxAgeMs) {
  throw new Error('Signature expired.');
}

const payload = { ...body, token, action, ts };
if (actor) {
  payload.actor = actor;
}
payload._signature = `sha256=${expectedHex}`;
payload._validatedAt = new Date().toISOString();

const outputs = [[], []];
if (action === 'approve') {
  outputs[0].push({ json: payload });
} else if (action === 'reject') {
  outputs[1].push({ json: payload });
} else {
  throw new Error(`Unsupported action "${action}".`);
}

return outputs;

const action = String($json.action || '').toLowerCase();
if (action && action !== 'approve') {
  return [];
}

const token = String($json.token || '').trim();
if (!token) {
  throw new Error('Missing approval token.');
}

const store = $getWorkflowStaticData('global');
const pendingStore = (store.pendingApprovals && typeof store.pendingApprovals === 'object') ? store.pendingApprovals : null;
if (!pendingStore) {
  throw new Error('No pending approvals are registered.');
}

const record = pendingStore[token];
if (!record) {
  throw new Error('Unknown approval token.');
}

const status = record.status || 'Pending';
if (status !== 'Pending') {
  throw new Error(`Approval token already resolved (${status}).`);
}

const now = new Date();
const expiresAtMs = record.expires_at ? Date.parse(record.expires_at) : null;
