const columns = ['WhenFound','Type','Summary','Detail','SourceLink','SourceType','ApproveLink','RejectLink','Status','Token','Action','ExpiresAt','ProcessedAt','Actor'];

function normalizeRow(row) {
  const normalized = {};
  for (const key of columns) {
    const value = row && Object.prototype.hasOwnProperty.call(row, key) ? row[key] : row && Object.prototype.hasOwnProperty.call(row, key.toLowerCase()) ? row[key.toLowerCase()] : '';
    normalized[key] = value == null ? '' : String(value).trim();
  }
  return normalized;
}

