const existingItems = $items(1) || [];
const existingMap = new Map();
for (let index = 0; index < existingItems.length; index++) {
  const entry = existingItems[index];
  if (!entry || typeof entry.json !== 'object') continue;
  const row = entry.json;
  const token = String(row.Token || row.token || '').trim();
  if (!token) continue;
  existingMap.set(token, { row, index });
}

const appendItems = [];
const updateItems = [];

for (const rawRow of signedRows) {
  const normalized = normalizeRow(rawRow || {});
  const token = normalized.Token;
  if (!token) continue;
  const existing = existingMap.get(token);
  if (!existing) {
    appendItems.push({ ...normalized, _action: 'append' });
    continue;
  }
  const prev = normalizeRow(existing.row || {});
  let changed = false;
  for (const column of columns) {
    const prevVal = prev[column];
    const nextVal = normalized[column];
    if (prevVal !== nextVal) {
      changed = true;
      break;
    }
  }
  if (changed) {
    updateItems.push({ ...normalized, _action: 'update' });
  }
}

if (!appendItems.length && !updateItems.length) {
  return [[], []];
}

return [
  appendItems.map((row) => ({ json: row })),
  updateItems.map((row) => ({ json: row })),
];

